import type { Metadata } from 'next';

/* The live site answers on www; the bare domain redirects there */
export const SITE_URL = 'https://www.cyberlounge.net';
export const SITE_NAME = 'Cyberlounge';

export const PROFILES = [
  'https://github.com/naperry2011',
  'https://www.linkedin.com/in/naperry2011/',
  'https://medium.com/@naperry2011',
];

/* Generated by src/app/opengraph-image.tsx; set here so pages with their own share tags keep it */
const SHARE_IMAGE = { url: '/opengraph-image', width: 1200, height: 630, alt: 'Cyberlounge: the quest log of Nicholas Perry' };

/* Title, description, canonical and share tags for one page. Path is site-relative ('/' for home). */
export function pageMeta(path: string, title: string, description: string): Metadata {
  return {
    title,
    description,
    alternates: { canonical: path },
    openGraph: { title, description, url: path, siteName: SITE_NAME, locale: 'en_US', type: 'website', images: [SHARE_IMAGE] },
    twitter: { card: 'summary_large_image', title, description, images: [SHARE_IMAGE.url] },
  };
}

export const PERSON_ID = SITE_URL + '/#person';

/* Structured data describing the site owner; every fact here is also visible on the site */
export const personJsonLd = {
  '@type': 'Person',
  '@id': PERSON_ID,
  name: 'Nicholas Perry',
  url: SITE_URL,
  image: SITE_URL + '/profile.jpg',
  jobTitle: 'Site Reliability Engineer',
  description: 'Builds apps and websites after hours.',
  sameAs: PROFILES,
};
